 * This project uses @Incubating APIs which are subject to change.
 */

pluginManagement {
    // The kdaisyui Gradle plugin, so example-app can apply it; see gradle-plugin/settings.gradle.kts.
    includeBuild("gradle-plugin")
}

plugins {
    // Apply the foojay-resolver plugin to allow automatic download of JDKs
    id("org.gradle.toolchains.foojay-resolver-convention") version "1.0.0"
}

rootProject.name = "kdaisyui"

// The one place the root build's projects find their dependencies, the root's Kover toolchain
// included. buildSrc and gradle-plugin are builds of their own and declare theirs.
dependencyResolutionManagement {
    repositories {
        mavenCentral()
    }
}

include("lib")
include("ktor-integration")
include("bom")
include("example-app")
include("e2e-tests")
include("doc-snippets")
include("build-checks")
